#include <iostream>
#include <string>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    string s;
    if(cin >> s) {
        if(s.length() >= 2){
            char a = s[0];
            char b = s[1];

            if (a > b) {
                cout << a << ">" << b << "\n";
            } else if (a < b) {
                cout << a << "<" << b <<"\n";                                    
            }  else {
                cout << a << "=" << b <<"\n";  
            }                                              }
         }        



    return 0;
   }

