const fs = require('fs')
function solve() {

    const input = require('fs').readFileSync(0, 'utf8').trim();
    if (!input) return;

    const s = input.split(/\s+/)[0];
    if (s && s.length >= 2) {
    const a = s[0];
    const b = s[1];

        if (a > b) {
            console.log(`${a}>${b}`);            
            }
        else if (a < b) {
            console.log(`${a}<${b}`);       
            }
        else {
            console.log(`${a}=${b}`);
            }        
    }

}

solve();

